// Two different problems, two different tools.
//
// A BUTTON should grow to clear the 44pt iOS minimum, so it takes a
// className — the consumer-override path these components are built for,
// resolved through cn().
const TOUCH = 'min-h-11 min-w-11';
// A SWITCH or CHECKBOX must NOT grow: its size is its design (44x24 and
// 16x16, measured against Safari), and stretching it to 44pt square turned
// the switch into a circle and the checkbox into a slab. Their touch target
// grows instead of their box — which is what hitSlop is for, and what a web
// page would do with a padded <label>.
//
// hitSlop is clipped by ancestor bounds: UIKit stops descending as soon as a
// point falls outside a parent, so slop hanging outside the row is slop that
// never gets hit-tested. The row therefore has to be at least as tall as the
// target it is meant to contain — hence TOUCH_ROW below. Sideways the slop
// stays inside half the 16pt gap so two neighbouring controls never claim
// the same point.
const TOUCH_SLOP = {top: 14, bottom: 14, left: 8, right: 8};
// A row that gives its controls somewhere to put their slop.
const TOUCH_ROW = 'flex flex-row flex-wrap items-center gap-4 min-h-11';

function ButtonsSection(): React.Node {
  const [lastAction, setLastAction] = useState('none');
  return (
    <DemoSection
      title="Button"
      description="Six variants from one cva() call. The demo adds a 44pt minimum through className — the consumer-override path the components are built for."
      code={`import {Button} from '@/components/ui/button';

<Button className="min-h-11 min-w-11">Default</Button>
<Button variant="secondary">Secondary</Button>
<Button variant="destructive">Destructive</Button>
<Button variant="outline">Outline</Button>
<Button variant="ghost">Ghost</Button>
<Button variant="link">Link</Button>`}>
      <div className="flex flex-row flex-wrap gap-2">
        <Button className={TOUCH} onClick={() => setLastAction('default')}>
          Default
        </Button>
        <Button
          className={TOUCH}
          variant="secondary"
          onClick={() => setLastAction('secondary')}>
          Secondary
        </Button>
        <Button
          className={TOUCH}
          variant="destructive"
          onClick={() => setLastAction('destructive')}>
          Destructive
        </Button>
        <Button
          className={TOUCH}
          variant="outline"
          onClick={() => setLastAction('outline')}>
          Outline
        </Button>
        <Button
          className={TOUCH}
          variant="ghost"
          onClick={() => setLastAction('ghost')}>
          Ghost
        </Button>
        <Button
          className={TOUCH}
          variant="link"
          onClick={() => setLastAction('link')}>
          Link
        </Button>
      </div>
      <span className="mt-2 block text-sm text-muted-foreground">
        Last pressed: {lastAction}
      </span>
    </DemoSection>
  );
}

