function AccordionSection(): React.Node {
  return (
    <DemoSection
      title="Accordion"
      description="Single type, collapsible; the chevron rotates through a data-[state=open] transform rule."
      code={`<Accordion type="single" collapsible>
  <AccordionItem value="a">
    <AccordionTrigger>Is it accessible?</AccordionTrigger>
    <AccordionContent>Yes — the shims carry the aria surface.</AccordionContent>
  </AccordionItem>
</Accordion>`}>
      {/*
        * `text-foreground` because the accordion is the one component here that
        * INHERITS its colour instead of setting one. On the web it inherits from
        * `body`, which shadcn's base layer gives `bg-background text-foreground`
        * — and that layer is deliberately not installed here, because its
        * preflight reset fights the user-agent styles. So the trigger fell back
        * to a colour that does not follow the scheme, and in dark mode it was
        * dark text on a dark page: the rows were there, and invisible.
        */}
      <Accordion className="text-foreground" type="single" collapsible={true}>
        <AccordionItem value="a">
          <AccordionTrigger className="min-h-11">
            Is it accessible?
          </AccordionTrigger>
          <AccordionContent>
            Yes — the shims carry the aria surface.
          </AccordionContent>
        </AccordionItem>
        <AccordionItem value="b">
          <AccordionTrigger className="min-h-11">
            Is it styled?
          </AccordionTrigger>
          <AccordionContent>
            By its own Tailwind classes, resolved by the fork.
          </AccordionContent>
        </AccordionItem>
      </Accordion>
    </DemoSection>
  );
}


/*
 * shadcn's base layer applies `bg-background text-foreground` to <body>. There
 * is no <body> here, so the screen root carries the half that matters.
 *
 * Every component that states its own text colour was fine without it, which
 * is why this went unnoticed: the ones that INHERIT — `outline` and `ghost`
 * buttons, the form labels, the dialog trigger — fell back to the platform's
 * default instead of the theme's, and in dark mode that is dark text on a
 * dark page. Preflight's `button { color: inherit }` is the other half; it
 * cancels the user-agent colour, and this supplies what replaces it.
 */
function Themed({children}: {children: React.Node}): React.Node {
  /* $FlowExpectedError[not-a-component] intrinsic <div> tag */
  return <div className="text-foreground">{children}</div>;
}

